public class MyTransformer implements ClassTransformer {
    @Override
    public byte[] transform(ClassFileTransformer transformer, ClassFile cf) {
        // Get the method count of the class
        int methodCount = cf.getMethodCount();

        // Loop through each method
        for (int i = 0; i < methodCount; i++) {
            Method method = cf.getMethod(i);

            // Check if the method is the one we're interested in
            if (method.getName().equals("myMethod")) {
